def separate_paren_groups(paren_string: str) -> List[str]:
    results = []
    stack = []
    current_group = []
    for char in paren_string.replace(" ", ""):
        if char == '(':
            stack.append(char)
            current_group.append(char)
        elif char == ')':
            stack.pop()
            current_group.append(char)
            if not stack:
                results.append(''.join(current_group))
                current_group = []
    return results

