def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict
    from typing import List, Tuple

    # Build the grid from the list of tuples
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # Initialize DP table
    dp = defaultdict(lambda: float('-inf'))
    dp[(0, 0, 0, 0)] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            x1, y1, v1 = i, j, grid[i][j]
            for x2 in range(N):
                for y2 in range(N):
                    v2 = grid[x2][y2]
                    if x1 != x2 or y1 != y2:
                        dp[(x1, y1, x2, y2)] = max(dp[(x1, y1, x2, y2)], dp[(x1-1, y1-1, x2-1, y2-1)] + v1 + v2)
                    dp[(x1, y1, x2, y2)] = max(dp[(x1, y1, x2, y2)], dp[(x1-1, y1, x2-1, y2)] + v1)
                    dp[(x1, y1, x2, y2)] = max(dp[(x1, y1, x2, y2)], dp[(x1, y1-1, x2, y2-1)] + v1)
                    dp[(x1, y1, x2, y2)] = max(dp[(x1, y1, x2, y2)], dp[(x1-1, y1, x2, y2)] + v2)
                    dp[(x1, y1, x2, y2)] = max(dp[(x1, y1, x2, y2)], dp[(x1, y1-1, x2, y2)] + v2)

    # The result is the maximum value in the DP table
    return max(dp.values())

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    INF = float('-inf')
    dp = [[[-INF for _ in range(2)] for _ in range(N)] for _ in range(N)]

    # Initialize the grid with the given values
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        grid[x-1][y-1] = v

    # Base case initialization
    dp[0][0][0] = grid[0][0]
    dp[0][0][1] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i > 0:
                for k in range(2):
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
            if j > 0:
                for k in range(2):
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j])
            if i > 0 and j > 0:
                for k in range(2):
                    for l in range(2):
                        if k == l:
                            continue
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][l] + grid[i][j])

    # The result is the maximum value we can collect on two paths
    return max(dp[N-1][N-1])

