def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, k):
        if i == N:
            return 0
        if k == 0:
            return int(num_str[i:])

        max_val = 0
        for j in range(i, N):
            left = int(num_str[i:j+1])
            right = dp(j+1, k-1)
            max_val = max(max_val, left * right)

        return max_val

    return dp(0, K)

def max_product(num_str: str, N: int, K: int) -> int:
    # Initialize a 2D array to store maximum products
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Fill the dp array
    for i in range(1, N + 1):
        for j in range(1, min(i, K + 1)):
            max_val = 0
            for k in range(i - 1, j - 2, -1):
                curr_val = int(num_str[k:i]) * dp[k][j - 1]
                max_val = max(max_val, curr_val)
            dp[i][j] = max(dp[i][j-1], max_val)

    return dp[N][K]

def max_product(num_str: str, N: int, K: int) -> int:
    from collections import deque

    def multiply(a, b):
        return int(a) * int(b)

    def get_max_product(nums, k):
        max_heap = deque()
        for num in nums:
            max_heap.extend([num * multiplier for multiplier in max_heap])
            max_heap.append(num)

        while k > 0:
            max_heap.popleft()
            k -= 1

        return max(max_heap)

    if K == 0:
        return int(num_str)

    nums = [num_str[i:i+2] for i in range(0, N, 2)]
    return get_max_product(nums, K)

