def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return total % 11

    isbn_parts = isbn.split('-')
    isbn_without_check = isbn_parts[0] + isbn_parts[1] + isbn_parts[2]
    current_checksum = calculate_checksum(isbn_without_check)
    correct_checksum = 11 - (current_checksum % 11)
    if correct_checksum == 11:
        correct_checksum = 0
    if correct_checksum == 10:
        correct_checksum = 'X'

    if str(correct_checksum) == isbn_parts[-1]:
        return "Right"
    else:
        isbn_parts[-1] = str(correct_checksum)
        return '-'.join(isbn_parts)

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        sum = 0
        for i in range(12):
            digit = int(isbn[i]) if isbn[i] != 'X' else 10
            sum += digit * (13 - i)
        return sum % 11

    parts = isbn.split('-')
    isbn = ''.join(parts)

    if isbn[-1] == 'X':
        isbn = isbn[:-1] + '10'

    calculated_checksum = calculate_checksum(isbn)

    if calculated_checksum == 0:
        return "Right"
    else:
        for i in range(10):
            test_isbn = isbn[:-1] + str(i)
            if calculate_checksum(test_isbn) == 0:
                return '-'.join(parts[:-1]) + '-' + test_isbn[-1] + '-' + parts[-1]

def verify_isbn(isbn: str) -> str:
    """
    Verify the correctness of a given ISBN number and correct it if necessary.

    :param isbn: A string representing the ISBN number to be verified. The format should be 'x-xxx-xxxxx-x',
                  where 'x' is a digit, and the last 'x' could also be 'X' representing the checksum digit.
    :return: A string that is either "Right" if the ISBN checksum is correct, or the corrected ISBN number
             in the same format as the input if the checksum is incorrect.
    """
    def verify_checksum(isbn):
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char) if char != 'X' else 10
            total += digit * (10 - i)
        return total % 11 == 0

    if len(isbn) != 17 or isbn[3] != '-' or isbn[7] != '-' or isbn[12] != '-':
        return isbn

    original_checksum = isbn[-1]
    if verify_checksum(isbn[:-1]):
        return "Right"

    for i in range(10):
        corrected_isbn = isbn[:-1] + str(i)
        if verify_checksum(corrected_isbn):
            return corrected_isbn

    return isbn

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    horizontal_aisles = [0] * N
    vertical_aisles = [0] * M

    for pair in chatting_pairs:
        (Xi, Yi), (Pi, Qi) = pair
        if Xi == Pi:  # Chatting pair is in the same row
            if Yi < Qi:
                vertical_aisles[Xi - 1] += 1
            else:
                vertical_aisles[Xi] += 1
        elif Yi == Qi:  # Chatting pair is in the same column
            if Xi < Pi:
                horizontal_aisles[Yi - 1] += 1
            else:
                horizontal_aisles[Yi] += 1

    horizontal_solutions = []
    for i in range(N - 1):
        if horizontal_aisles[i] > 0:
            count = 0
            for pair in chatting_pairs:
                (Xi, Yi), (Pi, Qi) = pair
                if Yi == i + 1 or Yi == i + 2:
                    if Xi < Pi:
                        count += 1
                    else:
                        count -= 1
            horizontal_solutions.append((count, i + 1))

    vertical_solutions = []
    for i in range(M - 1):
        if vertical_aisles[i] > 0:
            count = 0
            for pair in chatting_pairs:
                (Xi, Yi), (Pi, Qi) = pair
                if Xi == i + 1 or Xi == i + 2:
                    if Yi < Qi:
                        count += 1
                    else:
                        count -= 1
            vertical_solutions.append((count, i + 1))

    horizontal_aisles_solution = max(horizontal_solutions, key=lambda x: x[0])[1] if horizontal_solutions else 0
    vertical_aisles_solution = max(vertical_solutions, key=lambda x: x[0])[1] if vertical_solutions else 0

    return str(horizontal_aisles_solution), f"{vertical_aisles_solution} {horizontal_aisles_solution}" if K == 0 and L == 0 else str(vertical_aisles_solution)

