def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ''

    root = postorder[-1]
    inorder_index = inorder.index(root)

    left_inorder = inorder[:inorder_index]
    right_inorder = inorder[inorder_index + 1:]

    left_postorder = postorder[:inorder_index]
    right_postorder = postorder[inorder_index:-1]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

