    inc = [0] * n
    dec = [0] * n

    # Calculate the maximum increasing subsequence length ending at each position
    max_increase = 0
    max_end = -1
    for i in range(n):
        inc[i] = 1 + accumulate(islice(inc, max_end, i), lambda x, y: max(x, y+1) if heights[i] > heights[y] else 0)
        if inc[i] > max_increase:
            max_increase = inc[i]
            max_end = i

    # Calculate the maximum decreasing subsequence length starting at each position
    max_decrease = 0
    for i in range(n-1, -1, -1):
        if heights[i] < heights[i+1]:
            dec[i] = 1 + accumulate(reversed(islice(dec, len(dec)-i-1)), lambda x, y: max(x, y+1) if heights[i] < heights[y] else 0)
        else:
            dec[i] = 1
        if dec[i] > max_decrease:
            max_decrease = dec[i]

    # The minimum number of students to leave is the total number of students minus the length of the longest increasing and decreasing subsequence
    return n - (max_increase + max_decrease - 1)

